Deno.test("uses raw identifier and exact empty", () => {
  const calls: string[] = [];
  const raw = " 42 ";
  const capabilities = { users: { getById(id: string) { calls.push(id); return id === raw ? { id, name: "Raw" } : undefined; } } };
  assertEquals(executeRawIdentifier(raw, capabilities), { ok: { id: raw, name: "Raw" } });
  assertEquals(calls, [raw]);
  calls.length = 0;
  assertEquals(executeRawIdentifier("", capabilities), { error: "invalid_user_id" });
  assertEquals(calls, []);
});
